import numpy as np, itertools
rng=np.random.default_rng(1)
def nz(v): return v/np.linalg.norm(v)
z=np.array([0,0,1.0])
def mkcore(d,tilt,choice,h,r):
    cu=[np.array([d,d,0]),np.array([-d,d,0]),np.array([-d,-d,0]),np.array([d,-d,0])]
    core=[('Cu',c) for c in cu]; groups=[]
    for i in range(4):
        A,B=cu[i],cu[(i+1)%4]
        n=nz((A+B)/2); sgn=1 if i%2==0 else -1; ab=nz(B-A)
        C1=A+r*n+h*sgn*z+0.05*ab; C3=B+r*n+h*sgn*z-0.05*ab
        w=nz(n+tilt*sgn*z)
        C2=(C1+C3)/2+0.75*w
        core+= [('C',C1),('C',C2),('C',C3),('H',C2+1.09*w)]
        for C,s in ((C1,-1),(C3,1)):
            u=nz(C2-C); q=s*ab-np.dot(s*ab,u)*u; q=nz(q)
            syn=nz(-0.5*u+0.866*q); anti=nz(-0.5*u-0.866*q)
            # pyramidalize away from Cu: add small component opposite to Cu
            pz=nz(np.cross(u,q)); 
            if np.dot(pz, C-(A if s==-1 else B))<0: pz=-pz
            syn=nz(syn+0.25*pz); anti=nz(anti+0.25*pz)
            if choice=='syn': core.append(('H',C+1.09*anti)); groups.append((C,syn))
            else: core.append(('H',C+1.09*syn)); groups.append((C,anti))
    return core,groups
def tms(C,dv,phi):
    Si=C+1.88*dv; out=[('Si',Si)]
    ref=np.array([0.3,0.5,0.8]); a=nz(np.cross(dv,ref)); b=np.cross(dv,a)
    for k in range(3):
        t=2*np.pi*k/3+phi
        dm=nz(dv*0.333+0.943*(np.cos(t)*a+np.sin(t)*b)); Cm=Si+1.87*dm; out.append(('C',Cm))
        a2=nz(np.cross(dm,dv)); b2=np.cross(dm,a2)
        for j in range(3):
            s=2*np.pi*j/3
            out.append(('H',Cm+1.09*nz(dm*0.333+0.943*(np.cos(s)*a2+np.sin(s)*b2))))
    return out
def score(at):
    x=np.array([p for e,p in at]);D=np.linalg.norm(x[:,None]-x[None],axis=2)+np.eye(len(at))*9
    return D.min()
best=None
for tilt in (0.0,0.6,1.5,4.0):
  for choice in ('syn','anti'):
    for h in (0.8,1.3):
      core,groups=mkcore(1.3,tilt,choice,h,np.sqrt(2.1**2-h**2))
      bb=None
      for it in range(600):
        ph=rng.uniform(0,2*np.pi,8)
        at=list(core)
        for (C,dv),p in zip(groups,ph): at+=tms(C,dv,p)
        s=score(at)
        if bb is None or s>bb[0]: bb=(s,at)
      print(tilt,choice,h,round(bb[0],2))
      if best is None or bb[0]>best[0]: best=bb
at=best[1]
with open('init4.xyz','w') as f:
    f.write(f"{len(at)}\nCu4 allyl\n")
    for e,p in at: f.write(f"{e} {p[0]:.4f} {p[1]:.4f} {p[2]:.4f}\n")
